# -------------------- Gantry, Collimator, Field and Couch Display value verification functions for default view --------------------
# (note: Field View > button can be used to change view)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_gantry_set_value() -> opt[float]:
    """Locates the main Verified Treatment window > then returns the Gantry Set value from the default view if found

    :return float: Value if found, else None
    """
    if __find_verified_treatment_Window():
        obj_text_value = CommonActions.get_uneditable_field_objects_text_value(VerifiedTreatmentObjects.verified_Treatment_Set_Gantry_Angle_Field)
        if obj_text_value is not None:
            return float(obj_text_value)

